//#region ../ui/src/live-lobby/types.ts
/** Relic logs closed/empty slots as Id -1 with Type 3 or 6. Real skirmish AI is Id -1 with Type 1. */
function isOccupiedLiveLobbyPlayer(player) {
	if (player.playerId === -1) return player.type === 1;
	return player.playerId > 0;
}
function isAlliesRace(race) {
	return race === 0 || race === 2;
}
function isAxisRace(race) {
	return race === 1 || race === 3;
}
function teamPlayers(players, team) {
	return players.filter(isOccupiedLiveLobbyPlayer).filter((player) => team === "allies" ? isAlliesRace(player.race) : isAxisRace(player.race));
}
function defaultLiveLobbyPlayerLabel(player) {
	if (player.alias.trim()) return player.alias;
	if (player.playerId === -1) return "CPU opponent";
	return `Player ${player.index + 1}`;
}
//#endregion
export { teamPlayers as a, isOccupiedLiveLobbyPlayer as i, isAlliesRace as n, isAxisRace as r, defaultLiveLobbyPlayerLabel as t };
