import { s as safeInternalPath } from "../../../chunks/src.js";
import { t as failFrom } from "../../../chunks/unwrap.js";
import { fail, redirect } from "@sveltejs/kit";
//#region src/routes/login/+page.server.ts
var actions = { default: async ({ request, locals }) => {
	const form = await request.formData();
	const email = String(form.get("email") ?? "");
	const password = String(form.get("password") ?? "");
	if (!email || !password) return fail(400, {
		message: locals.t("Enter your email and password."),
		email
	});
	const result = await locals.services.auth().login(email, password);
	if (result.isErr()) return failFrom({
		...result.error,
		message: locals.t(result.error.message)
	}, { email });
	redirect(303, safeInternalPath(form.get("redirect"), locals.locale));
} };
//#endregion
export { actions };
