import { u as recentCommunityQuery } from "../../chunks/replays.js";
//#region src/routes/+page.server.ts
var prerender = false;
var load = async ({ locals, setHeaders }) => {
	if (!locals.user) setHeaders({ "cache-control": "public, s-maxage=15, stale-while-revalidate=60" });
	const replays = locals.services.replays();
	const liveLobbies = locals.services.liveLobbies().list().unwrapOr([]);
	liveLobbies.catch(() => {});
	const [recentMatches, streams] = await Promise.all([replays.getHistory(recentCommunityQuery(), 10).map((list) => list.items).unwrapOr([]), locals.services.twitch().listStreams().unwrapOr([])]);
	return {
		liveLobbies,
		recentMatches,
		streams
	};
};
//#endregion
export { load, prerender };
