var actions = { default: async ({ request, locals }) => {
	const form = await request.formData();
	const email = String(form.get("email") ?? "");
	const password = String(form.get("password") ?? "");
	if (password !== String(form.get("passwordConfirm") ?? "")) return fail(400, {
		message: locals.t("Passwords do not match."),
		email
	});
	if (password.length < 8) return fail(400, {
		message: locals.t("Password must be at least 8 characters."),
		email
	});
	const result = await locals.services.auth().register(email, password);
	if (result.isErr()) return failFrom({
		...result.error,
		message: locals.t(result.error.message)
	}, { email });
	redirect(303, localizeHref("/", locals.locale));
} };
//#endregion
export { actions };
