//#region src/routes/api/replay-file/[id]/+server.ts
function errorResponse(status, message, retryAfter) {
	const headers = { "Cache-Control": "no-store" };
	if (retryAfter !== void 0) headers["Retry-After"] = String(retryAfter);
	return new Response(message, {
		status,
		headers
	});
}
var GET = async ({ locals, params, getClientAddress }) => {
	const result = await locals.services.replays().getFile(params.id, getClientAddress());
	if (result.isErr()) return errorResponse(result.error.status, result.error.message, result.error.retryAfter);
	const file = result.value;
	return new Response(file.body, { headers: {
		"Content-Type": file.contentType,
		"Content-Disposition": `attachment; filename="${file.filename.replace(/"/g, "")}"`,
		"Cache-Control": "public, max-age=3600"
	} });
};
//#endregion
export { GET };
